-- 新キャラ ミネ（相手も自分も眠ってしまう）
INSERT INTO puzzle_allies (name, kind, rarity, in_gacha, element, hp, atk, sort_order, description, art_prompt, skill_name, skill_type, skill_power, skill_effect)
SELECT 'ミネ', 'art', 4, 1, 'dark', 220, 20, 161, '休憩室の主。彼女があくびをすると、営業所全体が眠くなる。', 'photorealistic portrait of a sleepy young Japanese woman in a taxi company uniform yawning in a dim rest room, soft purple light, cozy, 8k', 'みんなおやすみ', 'attack', 100, 'sleep_both'
WHERE NOT EXISTS (SELECT 1 FROM puzzle_allies WHERE name='ミネ');

CREATE TABLE IF NOT EXISTS puzzle_chapters (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  number      INTEGER NOT NULL,
  title       TEXT    NOT NULL,
  subtitle    TEXT    NOT NULL DEFAULT '',
  intro       TEXT    NOT NULL DEFAULT '',
  is_active   INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS puzzle_stages (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  chapter_id  INTEGER NOT NULL,
  number      INTEGER NOT NULL,
  enemy_id    INTEGER NOT NULL,
  pre_text    TEXT    NOT NULL DEFAULT '[]',
  post_text   TEXT    NOT NULL DEFAULT '[]',
  reward_coins INTEGER NOT NULL DEFAULT 100
);
CREATE INDEX IF NOT EXISTS idx_puzzle_stages_ch ON puzzle_stages(chapter_id, number);
CREATE TABLE IF NOT EXISTS puzzle_progress (
  player_id   INTEGER NOT NULL,
  stage_id    INTEGER NOT NULL,
  clears      INTEGER NOT NULL DEFAULT 1,
  best_hp     INTEGER NOT NULL DEFAULT 0,
  cleared_at  TEXT DEFAULT (datetime('now','localtime')),
  PRIMARY KEY (player_id, stage_id)
);

INSERT INTO puzzle_chapters (number, title, subtitle, intro) SELECT 1, 'はじまりの営業所', '年末の足音', '新米ドライバーのあなたは、妖精バジルに導かれて初めての繁忙期に挑む。まずは営業所の周りから。' WHERE NOT EXISTS (SELECT 1 FROM puzzle_chapters WHERE number=1);
INSERT INTO puzzle_chapters (number, title, subtitle, intro) SELECT 2, '忘年会の夜', '街がざわめく', '12月。忘年会の街は人であふれ、トラブルもあふれる。渋滞と豪雨を越えて、年末の悪魔が待つ。' WHERE NOT EXISTS (SELECT 1 FROM puzzle_chapters WHERE number=2);
INSERT INTO puzzle_chapters (number, title, subtitle, intro) SELECT 3, '大晦日', 'カウントダウン', '今年最後の夜。クレームも、ゴネ客も、カウントダウンの魔神も、ぜんぶ今日のうちに片づける。' WHERE NOT EXISTS (SELECT 1 FROM puzzle_chapters WHERE number=3);
INSERT INTO puzzle_chapters (number, title, subtitle, intro) SELECT 4, '元日', '初日の出を追って', '年が明けた。初詣の行列、福袋の争奪戦、そして道をふさぐ大魔王。' WHERE NOT EXISTS (SELECT 1 FROM puzzle_chapters WHERE number=4);
INSERT INTO puzzle_chapters (number, title, subtitle, intro) SELECT 5, '真相', 'バジルの正体', '無線が消え、通信が途絶える。すべての敵を操っていたのは――。' WHERE NOT EXISTS (SELECT 1 FROM puzzle_chapters WHERE number=5);
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 1, (SELECT id FROM puzzle_enemies WHERE name='ワンメーターババア' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "ようこそ、繁忙期の世界へ。わたしはバジル、あなたの案内人よ。"}, {"who": "basil", "text": "最初のお客様は駅前の常連さん。短い距離でも、笑顔で乗せるのが基本！"}, {"who": "enemy", "text": "1円単位で釣りを出しなさいよ！"}]', '[{"who": "basil", "text": "お見事。短い距離は数をこなせば立派な売上になるの。"}]', 95 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=1) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='ワンメーターババア');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 2, (SELECT id FROM puzzle_enemies WHERE name='ミドリムシ' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "気をつけて。停めた瞬間に現れる緑の人…。"}, {"who": "ally:新人ドライバー", "text": "お、俺も初日にやられました！ 停めるなら駐車枠か乗り場ですよ！"}, {"who": "enemy", "text": "はい、違反ですね。"}]', '[{"who": "basil", "text": "停める場所を選ぶのも、ドライバーの技術よ。"}]', 110 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=2) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='ミドリムシ');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 3, (SELECT id FROM puzzle_enemies WHERE name='道を言わない客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「いつもの所」しか言わないお客様。乗る前にちゃんと確認しましょう。"}, {"who": "ally:新人オペレーター", "text": "りょ、了解…！ えっと、どこへ行けば…"}]', '[{"who": "basil", "text": "目印まで聞いておく。これが寝落ち対策にもなるの。"}]', 125 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=3) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='道を言わない客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 4, (SELECT id FROM puzzle_enemies WHERE name='酔っ払いサラリーマン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "終電を逃したサラリーマン。家の場所を覚えていないかも。"}, {"who": "enemy", "text": "うぃ〜…まっすぐ…まっすぐ…"}]', '[{"who": "basil", "text": "「はい」で答えられる聞き方を覚えた？ これは後で効いてくるわ。"}]', 140 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=4) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='酔っ払いサラリーマン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 5, (SELECT id FROM puzzle_enemies WHERE name='乗り逃げマン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「コンビニでお金おろしてくる」…その言葉、信じちゃだめ。"}, {"who": "ally:営業所の受付さん", "text": "お支払いは先に確認してくださいね！ いってらっしゃい！"}]', '[{"who": "basil", "text": "降りる前に支払い。鉄則ね。"}]', 155 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=5) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='乗り逃げマン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 6, (SELECT id FROM puzzle_enemies WHERE name='行き先を言わない常連' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "常連さんは運転手を試してくるの。「いつもの」で分かるはず、って。"}, {"who": "enemy", "text": "…言わなくても分かるだろ？"}]', '[{"who": "basil", "text": "分からないときは聞く。恥ずかしがらないで。"}]', 170 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=6) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='行き先を言わない常連');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 7, (SELECT id FROM puzzle_enemies WHERE name='領収書ちょうだいマン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "降りる直前に領収書。後ろの車がクラクションを鳴らしてる…。"}, {"who": "ally:釣り銭の魔法使い", "text": "領収書もお釣りも、魔法のように素早くね！"}]', '[{"who": "basil", "text": "慌てないこと。安全な場所に停めてから対応すればいいの。"}]', 185 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=7) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='領収書ちょうだいマン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 8, (SELECT id FROM puzzle_enemies WHERE name='「近いけどいい？」おじさん' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "300メートル先。しかも一万円札。"}, {"who": "enemy", "text": "近いけどいい？ あ、これ一万円ね。"}]', '[{"who": "basil", "text": "近くても一万円札でも、笑顔。それがプロ。"}]', 200 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=8) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='「近いけどいい？」おじさん');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 9, (SELECT id FROM puzzle_enemies WHERE name='深夜の値切り客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「ちょっとまけてよ」。メーターは法律で決まっているの。"}, {"who": "ally:班長", "text": "値切りには毅然と。でも口調はやさしく、な。"}]', '[{"who": "basil", "text": "班長の言うとおり。ルールは守って、言い方はやわらかく。"}]', 215 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=9) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='深夜の値切り客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=1), 10, (SELECT id FROM puzzle_enemies WHERE name='相席を要求する団体' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "5人で乗ろうとする団体。定員は4人よ。"}, {"who": "enemy", "text": "ちょっとだけ！ 詰めれば乗れるから！"}]', '[{"who": "basil", "text": "第1章クリア！ 営業所の周りは制覇ね。次は忘年会の街へ。"}]', 230 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=1) AND number=10) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='相席を要求する団体');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 1, (SELECT id FROM puzzle_enemies WHERE name='渋滞マン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "12月。街がざわめき始めたわ。"}, {"who": "ally:首都高の覇者 ハイウェイ・キング", "text": "首都高が止まる？ 俺の前では止まらん。裏道を教えてやろう。"}, {"who": "enemy", "text": "動かない…ぜんぶ動かない…"}]', '[{"who": "basil", "text": "渋滞は避けるもの。知っている道の数が武器になるの。"}]', 95 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=1) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='渋滞マン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 2, (SELECT id FROM puzzle_enemies WHERE name='ゲリラ豪雨' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "雨が降ると、傘のない人がみんなタクシーを探す。"}, {"who": "ally:雨の日の救世主 レインマスター", "text": "雨は味方だ。でも、ワイパーは最速にしておけ。"}]', '[{"who": "basil", "text": "雨の日は売上チャンス。でも事故も増える。慎重にね。"}]', 110 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=2) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='ゲリラ豪雨');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 3, (SELECT id FROM puzzle_enemies WHERE name='高速嫌いの客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「下道で行って」。到着まで2時間…。"}, {"who": "ally:高速料金の精霊", "text": "ETCなら料金所を光の速さで抜けられるのに…"}]', '[{"who": "basil", "text": "お客様の希望が最優先。でも時間の目安は伝えておきましょう。"}]', 125 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=3) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='高速嫌いの客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 4, (SELECT id FROM puzzle_enemies WHERE name='ETCカード忘れ' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "料金所の前で気づく絶望。"}, {"who": "ally:高速のETC", "text": "ピンポーン…が鳴らない。カード、入ってます？"}]', '[{"who": "basil", "text": "出庫前の確認リストに「ETCカード」を入れておいて。"}]', 140 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=4) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='ETCカード忘れ');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 5, (SELECT id FROM puzzle_enemies WHERE name='深夜のゲロ客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "乗った瞬間に不穏な顔色…。"}, {"who": "ally:洗車の達人 アワモリ", "text": "汚されたら俺に任せろ。でも先に袋を渡せ！"}]', '[{"who": "basil", "text": "袋は常備。窓は全開。安全な場所にすぐ停める。"}]', 155 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=5) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='深夜のゲロ客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 6, (SELECT id FROM puzzle_enemies WHERE name='車内で電話し続ける人' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "降りる場所を言う暇がないお客様。"}, {"who": "ally:無線機", "text": "どうぞ…どうぞ…こちらの無線も聞いてください、どうぞ。"}]', '[{"who": "basil", "text": "電話が終わる瞬間を逃さず、行き先を確認するの。"}]', 170 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=6) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='車内で電話し続ける人');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 7, (SELECT id FROM puzzle_enemies WHERE name='「急いで」連呼マン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "信号は変えられない。でもお客様は急いでいる。"}, {"who": "ally:六本木のナイトガイド", "text": "急いでるときほど落ち着いて。事故ったら一番遅いからな。"}]', '[{"who": "basil", "text": "そのとおり。安全第一が結局いちばん早い。"}]', 185 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=7) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='「急いで」連呼マン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 8, (SELECT id FROM puzzle_enemies WHERE name='道案内する客（間違ってる）' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「そこ右」→一方通行。"}, {"who": "ally:カーナビ君", "text": "300m先、右方向です…あ、違いました。"}]', '[{"who": "basil", "text": "お客様の案内でも、標識は自分の目で確認。"}]', 200 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=8) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='道案内する客（間違ってる）');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 9, (SELECT id FROM puzzle_enemies WHERE name='大荷物の帰省客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "トランクに入りきらないお土産。"}, {"who": "ally:上野の荷物運び", "text": "どんな大荷物も俺のトランク収納術で入る。見てろ。"}]', '[{"who": "basil", "text": "帰省客は距離が出る。荷物の積み方で差がつくわ。"}]', 215 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=9) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='大荷物の帰省客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 10, (SELECT id FROM puzzle_enemies WHERE name='無言で指差す客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "どっちを指しているのか分からない…。"}, {"who": "ally:無線の魔術師", "text": "「了解」の一言で、すべては決まる。"}]', '[{"who": "basil", "text": "指差しの先を復唱して確認。言葉にすれば間違いは減るの。"}]', 230 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=10) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='無言で指差す客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=2), 11, (SELECT id FROM puzzle_enemies WHERE name='年末繁忙期の悪魔' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "…来たわね。12月、営業所に降臨する悪魔。"}, {"who": "enemy", "text": "休みは消える。シフトは埋まる。"}, {"who": "basil", "text": "みんなの力を合わせて。必殺技のゲージをためて！"}]', '[{"who": "basil", "text": "第2章クリア！ 悪魔を退けた。でも、年末はまだ終わらない…。"}]', 245 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=2) AND number=11) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='年末繁忙期の悪魔');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 1, (SELECT id FROM puzzle_enemies WHERE name='クレーマー課長' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "今年最後の夜。「お宅の運転手がね」から始まる電話が30分。"}, {"who": "ally:課長のハンコ", "text": "承認！ 承認！ …ではなく、まず話を聞くのだ。"}]', '[{"who": "basil", "text": "言い返さない。営業所に相談。それでいいの。"}]', 95 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=1) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='クレーマー課長');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 2, (SELECT id FROM puzzle_enemies WHERE name='配車アプリの鬼キャンセル' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "到着1分前にキャンセル。心が折れそう…。"}, {"who": "ally:無線の神 ディスパッチャー・ゼロ", "text": "次の配車はもう入れてある。前を向け。"}]', '[{"who": "basil", "text": "キャンセルは次のお客様へのチャンス。切り替えて。"}]', 110 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=2) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='配車アプリの鬼キャンセル');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 3, (SELECT id FROM puzzle_enemies WHERE name='空港定額ゴネ客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「定額って聞いてない」。聞いてるのに。"}, {"who": "ally:羽田の女神 エアポート・マリア", "text": "羽田の乗り場はすべて定額。わたしが証人よ。"}]', '[{"who": "basil", "text": "定額のルールを説明できれば、ゴネ客は怖くない。"}]', 125 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=3) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='空港定額ゴネ客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 4, (SELECT id FROM puzzle_enemies WHERE name='赤信号ラッシュ' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "全部赤。すべて赤。"}, {"who": "ally:森の交通整理人 グリーンマン", "text": "俺の前で赤は許されない。グリーンウェーブ、行くぞ。"}]', '[{"who": "basil", "text": "信号のタイミングを読む。それも腕のうち。"}]', 140 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=4) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='赤信号ラッシュ');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 5, (SELECT id FROM puzzle_enemies WHERE name='教習所の鬼教官' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「はい、今の減点」。"}, {"who": "ally:点呼の番人", "text": "安全確認は点呼から始まっている。基本に戻れ。"}]', '[{"who": "basil", "text": "基本に忠実な人ほど、繁忙期に強いのよ。"}]', 155 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=5) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='教習所の鬼教官');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 6, (SELECT id FROM puzzle_enemies WHERE name='両替を要求する客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「一万円くずして」。千円札はもうない。"}, {"who": "ally:釣り銭の魔法使い", "text": "だから言ったでしょ、小銭は無限に用意しておくの。"}]', '[{"who": "basil", "text": "両替は自分が行く。ハンドブックに書いてあるでしょ？"}]', 170 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=6) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='両替を要求する客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 7, (SELECT id FROM puzzle_enemies WHERE name='ペットを隠して乗る客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "バッグが動いている…。"}, {"who": "ally:班長の犬", "text": "ワン！（仲間がいる…！）"}]', '[{"who": "basil", "text": "小動物はキャリーに入っていればOK。確認は丁寧に。"}]', 185 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=7) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='ペットを隠して乗る客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 8, (SELECT id FROM puzzle_enemies WHERE name='自転車を積みたい人' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "折りたためない自転車。"}, {"who": "ally:整備士ドラゴン", "text": "無理に積むな。トランクが壊れたら俺が修理だ。"}]', '[{"who": "basil", "text": "積めないものは積めない。代わりの方法を提案しましょう。"}]', 200 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=8) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='自転車を積みたい人');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 9, (SELECT id FROM puzzle_enemies WHERE name='吐き気の予兆マン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "顔色が緑。窓を全開に。"}, {"who": "ally:自販機の精", "text": "水を一本どうぞ…当たりは出ないけど。"}]', '[{"who": "basil", "text": "もう対応の型は覚えたわね。すぐ停める、外へ、袋。"}]', 215 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=9) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='吐き気の予兆マン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 10, (SELECT id FROM puzzle_enemies WHERE name='寝落ち常習犯' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "家の前で起きない…。"}, {"who": "ally:駐車場の猫", "text": "にゃー（起きないなら屋根から奇襲するにゃ）"}]', '[{"who": "basil", "text": "無理に触らない。営業所へ連絡。基本どおりで大丈夫。"}]', 230 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=10) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='寝落ち常習犯');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=3), 11, (SELECT id FROM puzzle_enemies WHERE name='大晦日のカウントダウン魔神' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "0時の瞬間、渋谷の全道路を封鎖する魔神…。"}, {"who": "ally:渋谷スクランブルの達人", "text": "人混みは避けて、少し離れて拾う。俺が道を開ける。"}, {"who": "enemy", "text": "10…9…8…"}]', '[{"who": "basil", "text": "第3章クリア！ あけましておめでとう！ …さあ、元日が始まるわ。"}]', 245 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=3) AND number=11) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='大晦日のカウントダウン魔神');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 1, (SELECT id FROM puzzle_enemies WHERE name='「前の車についていって」客' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "前の車も分かっていない…。"}, {"who": "ally:品川の新幹線ハンター", "text": "ついていくなら、見失わない距離を保て。"}]', '[{"who": "basil", "text": "無理な追従は事故のもと。安全な距離でね。"}]', 295 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=1) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='「前の車についていって」客');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 2, (SELECT id FROM puzzle_enemies WHERE name='深夜の大学生軍団' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "全員が別の場所に帰る。"}, {"who": "ally:池袋の路地マスター", "text": "順番に降ろせ。路地の最短ルートは俺が知ってる。"}]', '[{"who": "basil", "text": "降ろす順番を最初に決めておくと、揉めないの。"}]', 310 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=2) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='深夜の大学生軍団');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 3, (SELECT id FROM puzzle_enemies WHERE name='カラオケ帰りの合唱団' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "車内でアンコールが始まる…。"}, {"who": "ally:整備工場のラジオ", "text": "♪〜 負けずに同じ曲を流してやる。"}]', '[{"who": "basil", "text": "楽しそうなお客様は、楽しいまま降ろしてあげて。"}]', 325 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=3) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='カラオケ帰りの合唱団');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 4, (SELECT id FROM puzzle_enemies WHERE name='雪の日のスリップ魔' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "チェーンなしで坂を登らせようとする。"}, {"who": "ally:築地の早起きドライバー", "text": "朝4時の築地は凍ってる。坂は無理せず迂回だ。"}]', '[{"who": "basil", "text": "雪の日は無理をしない。これも立派な判断。"}]', 340 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=4) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='雪の日のスリップ魔');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 5, (SELECT id FROM puzzle_enemies WHERE name='首都高の渋滞ゴースト' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "事故もないのに動かない…。"}, {"who": "ally:首都高の覇者 ハイウェイ・キング", "text": "ゴーストか。俺のフルスロットルで消し飛ばす。"}]', '[{"who": "basil", "text": "渋滞情報はこまめに。入る前に判断ね。"}]', 355 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=5) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='首都高の渋滞ゴースト');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 6, (SELECT id FROM puzzle_enemies WHERE name='終電逃しの群れ' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "駅前にあふれる手、手、手。"}, {"who": "ally:終電の魔術師 ラストトレイン", "text": "終電が消えた瞬間が、俺たちの出番だ。"}]', '[{"who": "basil", "text": "つけ待ちが強いのはこういう場面。使い分けを覚えた？"}]', 370 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=6) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='終電逃しの群れ');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 7, (SELECT id FROM puzzle_enemies WHERE name='クリスマスイブのカップル' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "目的地が決まっていない二人…。"}, {"who": "ally:代官山のセレブ案内人", "text": "ロマンチックな場所なら、代官山にお任せを。"}]', '[{"who": "basil", "text": "提案ができる運転手は、チップより信頼をもらえるの。"}]', 385 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=7) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='クリスマスイブのカップル');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 8, (SELECT id FROM puzzle_enemies WHERE name='初詣の大行列' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "明治神宮の周りは動かない。"}, {"who": "ally:浅草の観光名人", "text": "初詣なら浅草もいいよ。雷門の前で記念写真はどう？"}]', '[{"who": "basil", "text": "混む場所は避けて、少し離れた所で降ろす。"}]', 400 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=8) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='初詣の大行列');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 9, (SELECT id FROM puzzle_enemies WHERE name='福袋の争奪戦' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "開店前の百貨店。荷物が倍になって帰ってくる。"}, {"who": "ally:丸の内のビジネス送迎", "text": "初売りの朝は丸の内から。エスコートはお任せを。"}]', '[{"who": "basil", "text": "初売りは朝が勝負。出番の時間を考えて。"}]', 415 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=9) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='福袋の争奪戦');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 10, (SELECT id FROM puzzle_enemies WHERE name='元日の初詣大行列ボス' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "参道の人の波が、巨大な竜に…！"}, {"who": "ally:銀座の守護竜 ギンザドラゴン", "text": "竜には竜だ。乗禁ブレス、行くぞ。"}, {"who": "enemy", "text": "ゴゴゴ…並べ…並べ…"}]', '[{"who": "basil", "text": "すごい…。あなた、本当に強くなったわね。"}]', 430 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=10) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='元日の初詣大行列ボス');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=4), 11, (SELECT id FROM puzzle_enemies WHERE name='渋滞大魔王' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "全ての道を一本道にする大魔王。元日の最後の壁よ。"}, {"who": "enemy", "text": "我が王国に抜け道など、ない。"}]', '[{"who": "basil", "text": "第4章クリア。…ねえ、ひとつ気づいてない？ 敵のこと、わたし、詳しすぎると思わない？"}]', 445 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=4) AND number=11) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='渋滞大魔王');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 1, (SELECT id FROM puzzle_enemies WHERE name='年始の二日酔いマン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "1月2日の朝。全部が遅い…。"}, {"who": "ally:休憩所のおじさん", "text": "二日酔いにはな、昔から言うんだが…（長い）"}]', '[{"who": "basil", "text": "…ふふ。あと少しで、全部わかるわ。"}]', 295 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=1) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='年始の二日酔いマン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 2, (SELECT id FROM puzzle_enemies WHERE name='消えた無線' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "配車が来ない。応答もない。おかしいわね…"}, {"who": "ally:無線機", "text": "ザザ…どうぞ…ザザ…バジ…ル…？"}, {"who": "enemy", "text": "……"}]', '[{"who": "basil", "text": "無線が消えた。でも、あなたはもう一人で走れる。"}]', 310 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=2) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='消えた無線');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 3, (SELECT id FROM puzzle_enemies WHERE name='バッテリー切れスマホ決済マン' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "「スマホで払います」→電源が落ちる。"}, {"who": "ally:営業所のポスター", "text": "安全運転！ 現金も用意！ 標語は裏切らない！"}]', '[{"who": "basil", "text": "最後の普通のお客様。この先は、普通じゃないわ。"}]', 325 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=3) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='バッテリー切れスマホ決済マン');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 4, (SELECT id FROM puzzle_enemies WHERE name='繁忙期シフトの魔王' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "12月のシフト表そのもの。休みのマスが存在しない…"}, {"who": "ally:営業所の植木", "text": "（光合成でみんなを癒やしてあげよう）"}, {"who": "enemy", "text": "休みなど、ない。"}]', '[{"who": "basil", "text": "よくやったわ。でも、まだ審査官が残ってる。"}]', 340 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=4) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='繁忙期シフトの魔王');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 5, (SELECT id FROM puzzle_enemies WHERE name='伝説のタクシーセンター審査官' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "1ミリの違反も見逃さない審査官。乗禁も、乗り場のルールも、全部見られてる。"}, {"who": "enemy", "text": "では、審査を始めます。"}, {"who": "ally:新宿の夜警", "text": "裏道も表道も、ルールを守って走れ。俺が見てる。"}]', '[{"who": "basil", "text": "合格ね。…じゃあ、最後に本当のことを話すわ。"}]', 355 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=5) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='伝説のタクシーセンター審査官');
INSERT INTO puzzle_stages (chapter_id, number, enemy_id, pre_text, post_text, reward_coins) SELECT (SELECT id FROM puzzle_chapters WHERE number=5), 6, (SELECT id FROM puzzle_enemies WHERE name='バジル【真の姿】' ORDER BY id LIMIT 1), '[{"who": "basil", "text": "ここまで来てくれて、ありがとう。"}, {"who": "basil", "text": "ワンメーターババアも、渋滞マンも、悪魔も…ぜんぶ、わたしが用意したの。"}, {"who": "basil", "text": "あなたを本物のドライバーにするために。さあ、最後のテストよ。"}, {"who": "enemy", "text": "……来なさい。"}]', '[{"who": "basil", "text": "…負けちゃった。でも、嬉しい。あなたはもう、どんな繁忙期でも大丈夫。"}, {"who": "basil", "text": "これからも案内人として、そばにいるわね。ゲームクリア、おめでとう！"}]', 370 WHERE NOT EXISTS (SELECT 1 FROM puzzle_stages WHERE chapter_id=(SELECT id FROM puzzle_chapters WHERE number=5) AND number=6) AND EXISTS (SELECT 1 FROM puzzle_enemies WHERE name='バジル【真の姿】');
